import sys,math
import numpy as np
from PIL import Image,ImageDraw
sys.path.insert(0,'/app/output');import gen
mask=gen.target_mask();routes=gen.component_routes(mask)
cam=Image.open('/app/runs/inspect_n/last/canvas_cam.jpg').crop((68,68,956,956)).resize((1024,1024),Image.Resampling.BILINEAR);g=np.array(cam).mean(2)
W=.004/gen.PX_M;T=.0004/gen.PX_M
for idx in [0,1,2,3]:
 name,route,comp=routes[idx];ys,xs=np.where(comp);pad=10;roi=np.zeros_like(comp);roi[max(0,ys.min()-pad):ys.max()+pad+1,max(0,xs.min()-pad):xs.max()+pad+1]=1
 actual=(g<120)&roi;target=comp
 base=((actual&target).sum()/(actual|target).sum());best=(base,('base',))
 cand_yaws=range(0,81,5)
 for yaw in cand_yaws:
  alpha=math.radians(-yaw)
  for du in range(-2,3):
   for dv in range(-2,3):
    can=Image.new('1',(1024,1024),0);d=ImageDraw.Draw(can);pts=[(x+du,y+dv) for y,x in route]
    for i in range(1,len(pts)):
     x0,y0=pts[i-1];x1,y1=pts[i];phi=math.atan2(y1-y0,x1-x0);w=W*abs(math.sin(phi-alpha))+T*abs(math.cos(phi-alpha));d.line((x0,y0,x1,y1),fill=1,width=max(1,int(round(w))))
    add=np.array(can).astype(bool)&roi;u=actual|add;inter=(u&target).sum();iou=inter/(u|target).sum()
    if iou>best[0]:best=(iou,('fixed',yaw,du,dv,int(add.sum()),int((add&actual).sum())))
 # for loops, adaptive route yaw with radial offset
 if idx in [1,2]:
  yy=np.array(gen.fitted_yaws(route,comp));ys0,xs0=np.where(comp);cx=xs0.mean();cy=ys0.mean()
  for off in [0.5,1,1.5,2,2.5,3]:
   pts=[]
   for y,x in route:
    dx=x-cx;dy=y-cy;norm=math.hypot(dx,dy);pts.append((x+off*dx/norm,y+off*dy/norm))
   can=Image.new('1',(1024,1024),0);d=ImageDraw.Draw(can)
   for i in range(1,len(pts)):
    x0,y0=pts[i-1];x1,y1=pts[i];phi=math.atan2(y1-y0,x1-x0);yaw=(yy[i-1]+yy[i])/2;w=W*abs(math.sin(phi+math.radians(yaw)))+T*abs(math.cos(phi+math.radians(yaw)));d.line((x0,y0,x1,y1),fill=1,width=max(1,int(round(w))))
   add=np.array(can).astype(bool)&roi;u=actual|add;inter=(u&target).sum();iou=inter/(u|target).sum()
   if iou>best[0]:best=(iou,('radial',off,int(add.sum()),int((add&actual).sum())))
 print(name,'baseline',round(base,4),'best one extra',best)
